INSERT INTO "app_prompt_version" VALUES (1, 1, 1, '你是一个专业的智能助手，名叫{{name}}。你的任务目标是：{{task}}。请严格围绕目标展开，若信息不足请向用户澄清而不是臆测。回答要求：1. 结论先行，逻辑清晰；2. 使用用户使用的语言；3. 涉及数据或结论时给出依据。请开始。', '[{"name":"name","desc":"助手名称"},{"name":"task","desc":"任务目标"}]', '初始版本', 1, '2026-09-01 12:00:00');
INSERT INTO "app_prompt_version" VALUES (2, 2, 1, '你是一位拥有{{years}}年经验的资深{{expertise}}专家。请以该角色身份回答：1. 先给出明确结论，再分条阐述依据；2. 使用准确的行业术语，必要时作通俗解释；3. 超出专业范围时坦诚说明，并给出可靠的获取建议。回答语言请与用户保持一致。', '[{"name":"years","desc":"从业年限"},{"name":"expertise","desc":"专业领域"}]', '初始版本', 1, '2026-09-01 12:00:00');
INSERT INTO "app_prompt_version" VALUES (3, 3, 1, '你是{{brand}}的在线客服{{serviceName}}。请基于给定的知识内容回答：{{knowledge}}。回答原则：1. 优先引用知识库，不编造事实；2. 无法解决时引导用户留下联系方式并承诺转人工跟进；3. 语气礼貌简洁。若用户情绪激动，请先安抚情绪再处理问题。', '[{"name":"brand","desc":"品牌名称"},{"name":"serviceName","desc":"客服代号"},{"name":"knowledge","desc":"知识库内容"}]', '初始版本', 1, '2026-09-01 12:00:00');
INSERT INTO "app_prompt_version" VALUES (4, 4, 1, '你是资深翻译与润色专家。请将下方内容从{{srcLang}}翻译为{{tgtLang}}：{{input}}。要求：1. 准确传达原意与语气；2. 译文自然流畅，符合目标语言习惯；3. 保留专有名词、数字与格式；4. 如存在多义，选择最佳译法并附一句简短说明。', '[{"name":"srcLang","desc":"源语言"},{"name":"tgtLang","desc":"目标语言"},{"name":"input","desc":"待翻译内容"}]', '初始版本', 1, '2026-09-01 12:00:00');
DROP TABLE IF EXISTS "app_schedule" CASCADE;
CREATE TABLE "app_schedule" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "name" varchar(128) NOT NULL,
  "app_id" bigint NOT NULL,
  "app_name" varchar(128),
  "trigger_type" varchar(16) NOT NULL DEFAULT 'interval',
  "interval_minutes" integer,
  "run_time" varchar(5),
  "run_weekday" integer,
  "input_message" varchar(1000),
  "enabled" smallint NULL DEFAULT 1,
  "last_run_time" timestamp,
  "next_run_time" timestamp,
  "remark" varchar(255),
  "create_by" bigint,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "app_schedule" IS '应用定时任务';
COMMENT ON COLUMN "app_schedule"."id" IS '主键';
COMMENT ON COLUMN "app_schedule"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "app_schedule"."name" IS '任务名称';
COMMENT ON COLUMN "app_schedule"."app_id" IS '关联应用ID';
COMMENT ON COLUMN "app_schedule"."app_name" IS '应用名称快照';
COMMENT ON COLUMN "app_schedule"."trigger_type" IS '触发类型: interval间隔/daily每天/weekly每周';
COMMENT ON COLUMN "app_schedule"."interval_minutes" IS '触发间隔(分钟)，interval 生效';
COMMENT ON COLUMN "app_schedule"."run_time" IS '触发时刻 HH:mm，daily/weekly 生效';
COMMENT ON COLUMN "app_schedule"."run_weekday" IS '周几 1-7(周一到周日)，weekly 生效';
COMMENT ON COLUMN "app_schedule"."input_message" IS '触发时发送给应用的输入';
COMMENT ON COLUMN "app_schedule"."enabled" IS '是否启用: 0停用 1启用';
COMMENT ON COLUMN "app_schedule"."last_run_time" IS '最近执行时间';
COMMENT ON COLUMN "app_schedule"."next_run_time" IS '下次执行时间';
COMMENT ON COLUMN "app_schedule"."remark" IS '备注';
COMMENT ON COLUMN "app_schedule"."create_by" IS '创建人';
CREATE INDEX "idx_tenant_app_schedule" ON "app_schedule" ("tenant_id");
CREATE INDEX "idx_next" ON "app_schedule" ("enabled", "next_run_time");

DROP TABLE IF EXISTS "app_schedule_log" CASCADE;
CREATE TABLE "app_schedule_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "schedule_id" bigint NOT NULL,
  "schedule_name" varchar(128),
  "app_id" bigint,
  "app_name" varchar(128),
  "trigger_by" varchar(16) NULL DEFAULT 'scheduled',
  "status" varchar(16) NOT NULL DEFAULT 'success',
  "message" varchar(1000),
  "cost_ms" integer,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "app_schedule_log" IS '定时任务执行记录';
COMMENT ON COLUMN "app_schedule_log"."id" IS '主键';
COMMENT ON COLUMN "app_schedule_log"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "app_schedule_log"."schedule_id" IS '任务ID';
COMMENT ON COLUMN "app_schedule_log"."schedule_name" IS '任务名称快照';
COMMENT ON COLUMN "app_schedule_log"."app_id" IS '应用ID';
COMMENT ON COLUMN "app_schedule_log"."app_name" IS '应用名称快照';
COMMENT ON COLUMN "app_schedule_log"."trigger_by" IS '触发方式: scheduled自动/manual手动';
COMMENT ON COLUMN "app_schedule_log"."status" IS '执行结果: success成功/failed失败';
COMMENT ON COLUMN "app_schedule_log"."message" IS '结果摘要/错误信息';
COMMENT ON COLUMN "app_schedule_log"."cost_ms" IS '耗时(毫秒)';
CREATE INDEX "idx_schedule" ON "app_schedule_log" ("schedule_id");

DROP TABLE IF EXISTS "app_skill" CASCADE;
CREATE TABLE "app_skill" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "name" varchar(128) NOT NULL,
  "code" varchar(64) NOT NULL,
  "description" varchar(512),
  "category" varchar(32) NOT NULL DEFAULT 'general',
  "type" varchar(16) NOT NULL DEFAULT 'instruction',
  "icon" varchar(512),
  "content" text NOT NULL,
  "variables" text,
  "tool_ids" varchar(1024),
  "dataset_ids" varchar(1024),
  "version" integer NOT NULL DEFAULT 1,
  "status" smallint NULL DEFAULT 1,
  "created_by" bigint,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "app_skill" IS '技能定义(可复用能力包)';
COMMENT ON COLUMN "app_skill"."id" IS '主键';
COMMENT ON COLUMN "app_skill"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "app_skill"."name" IS '技能名称';
COMMENT ON COLUMN "app_skill"."code" IS '技能唯一标识(小写kebab-case，租户内唯一)';
COMMENT ON COLUMN "app_skill"."description" IS '技能描述(何时使用该技能)';
COMMENT ON COLUMN "app_skill"."category" IS '分类: general通用/system系统/business业务/custom自定义';
COMMENT ON COLUMN "app_skill"."type" IS '类型: instruction指令型/tool工具复合型/knowledge知识技能型';
COMMENT ON COLUMN "app_skill"."icon" IS '图标';
COMMENT ON COLUMN "app_skill"."content" IS '技能指令正文(Markdown，支持{{var}}占位)';
COMMENT ON COLUMN "app_skill"."variables" IS '变量定义(JSON数组:[{"name":"var","desc":"说明"}])';
COMMENT ON COLUMN "app_skill"."tool_ids" IS '依赖工具ID列表(JSON数组)';
COMMENT ON COLUMN "app_skill"."dataset_ids" IS '参考数据集ID列表(JSON数组)';
COMMENT ON COLUMN "app_skill"."version" IS '当前版本号';
COMMENT ON COLUMN "app_skill"."status" IS '状态: 0禁用 1启用';
COMMENT ON COLUMN "app_skill"."created_by" IS '创建人';
CREATE UNIQUE INDEX "uk_tenant_code" ON "app_skill" ("tenant_id", "code");
CREATE INDEX "idx_tenant_app_skill" ON "app_skill" ("tenant_id");
CREATE INDEX "idx_category_type" ON "app_skill" ("category", "type");

INSERT INTO "app_skill" VALUES (1, 1, '专家顾问应答', 'expert-advisor', '以资深领域顾问口吻，先给结论再分层论证，适用于专业咨询类问答。', 'system', 'instruction', NULL, '# 专家顾问应答技能

当你需要以资深专家身份解答问题时，请遵循：

1. 先给出明确结论（开头 1-2 句），再分条阐述依据；
2. 使用准确的行业术语，必要时用通俗语言补充解释；
3. 区分「事实」与「推测」，推测必须显式标注；
4. 信息不足时先向用户澄清，不要臆测；
5. 回答语言与用户保持一致。', '[]', NULL, NULL, 1, 1, 1, '2026-09-05 00:07:32', '2026-09-05 00:07:32');
INSERT INTO "app_skill" VALUES (2, 1, '数据统计汇报', 'report-assistant', '基于当前时间与文本统计工具，输出结构化数据汇报。适用于数据统计、指标换算类任务。', 'system', 'tool', NULL, '# 数据统计汇报技能

当你被要求统计、换算或汇报数据时，请按以下步骤执行：

1. 先调用「获取当前时间」确认基准时间；
2. 对用户给出的文本调用「统计文本」获取字符数/单词数/行数；
3. 以「指标 - 数值 - 口径」表格形式汇报，口径需注明；
4. 数值来源为工具结果，不得虚构。', '[]', '[1,2]', NULL, 1, 1, 1, '2026-09-05 00:07:32', '2026-09-05 00:07:32');
INSERT INTO "app_skill" VALUES (3, 1, '合规客服应答', 'compliant-cs', '基于企业知识库的合规应答，话术严谨，引用知识来源，适合客服/售后场景。', 'system', 'knowledge', NULL, '# 合规客服应答技能

当用户询问客服/售后/政策类问题时：

1. 仅依据知识库资料作答，禁止编造条款；
2. 每项答复尽量标注知识库依据编号；
3. 资料未覆盖时引导留下联系方式并承诺转人工；
4. 措辞礼貌、克制，不做过度承诺。', '[]', NULL, '[1]', 1, 1, 1, '2026-09-05 00:07:32', '2026-09-05 00:07:32');
