DROP TABLE IF EXISTS "ops_alert_rule" CASCADE;
CREATE TABLE "ops_alert_rule" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "name" varchar(100),
  "metric" varchar(32),
  "operator" varchar(8) NULL DEFAULT '>=',
  "threshold" decimal(12, 4),
  "window_minutes" integer NULL DEFAULT 60,
  "level" varchar(16) NULL DEFAULT 'warning',
  "channels" varchar(128) NULL DEFAULT 'notification',
  "webhook_url" varchar(500),
  "enabled" smallint NULL DEFAULT 1,
  "remark" varchar(255),
  "last_fire_time" timestamp,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ops_alert_rule" IS '告警规则';
COMMENT ON COLUMN "ops_alert_rule"."id" IS '主键';
COMMENT ON COLUMN "ops_alert_rule"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ops_alert_rule"."name" IS '规则名称';
COMMENT ON COLUMN "ops_alert_rule"."metric" IS '指标: error_rate错误率/failures失败数/latency延迟/cost成本';
COMMENT ON COLUMN "ops_alert_rule"."operator" IS '比较符';
COMMENT ON COLUMN "ops_alert_rule"."threshold" IS '阈值';
COMMENT ON COLUMN "ops_alert_rule"."window_minutes" IS '统计窗口(分钟)';
COMMENT ON COLUMN "ops_alert_rule"."level" IS '级别: warning/critical';
COMMENT ON COLUMN "ops_alert_rule"."channels" IS '通知渠道: notification,email,webhook';
COMMENT ON COLUMN "ops_alert_rule"."webhook_url" IS 'Webhook地址';
COMMENT ON COLUMN "ops_alert_rule"."enabled" IS '是否启用: 0否 1是';
COMMENT ON COLUMN "ops_alert_rule"."remark" IS '备注';
COMMENT ON COLUMN "ops_alert_rule"."last_fire_time" IS '最近触发时间';
CREATE INDEX "idx_tenant_ops_alert_rule" ON "ops_alert_rule" ("tenant_id");

INSERT INTO "ops_alert_rule" VALUES (1, 1, '错误率过高预警', 'error_rate', '>=', 5.0000, 60, 'warning', 'notification,webhook', 'https://example.com/hooks/agent-platform-alert', 1, '应用错误率超过 5% 时触发告警', '2026-09-05 00:01:53', '2026-09-02 10:00:00', '2026-09-05 00:01:53');
INSERT INTO "ops_alert_rule" VALUES (2, 1, '运行失败数突增', 'failures', '>=', 10.0000, 60, 'critical', 'notification,email', NULL, 1, '60 分钟内运行失败超过 10 次', '2026-09-05 00:01:50', '2026-09-02 10:05:00', '2026-09-05 00:01:50');
INSERT INTO "ops_alert_rule" VALUES (3, 1, '月成本超预算', 'cost', '>=', 300.0000, 1440, 'warning', 'notification', NULL, 1, '月度累计成本超过 300 元提醒', '2026-09-05 00:01:45', '2026-09-02 10:10:00', '2026-09-05 00:01:45');
DROP TABLE IF EXISTS "publish_channel" CASCADE;
CREATE TABLE "publish_channel" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "app_id" bigint NOT NULL,
  "name" varchar(128) NOT NULL,
  "channel_type" varchar(24) NOT NULL,
  "config_json" text,
  "description" varchar(512),
  "enabled" smallint NOT NULL DEFAULT 1,
  "msg_count" bigint NOT NULL DEFAULT 0,
  "last_msg_at" timestamp,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "publish_channel" IS '发布-渠道管理';
COMMENT ON COLUMN "publish_channel"."id" IS '主键';
COMMENT ON COLUMN "publish_channel"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "publish_channel"."app_id" IS '绑定应用ID(app_agent.id)';
COMMENT ON COLUMN "publish_channel"."name" IS '渠道名称';
COMMENT ON COLUMN "publish_channel"."channel_type" IS '类型: wechat_mp公众号/feishu飞书/dingtalk钉钉/web网页/webhook';
COMMENT ON COLUMN "publish_channel"."config_json" IS '渠道配置(JSON，含凭证/校验token等)';
COMMENT ON COLUMN "publish_channel"."description" IS '描述';
COMMENT ON COLUMN "publish_channel"."enabled" IS '启用: 0停用 1启用';
COMMENT ON COLUMN "publish_channel"."msg_count" IS '累计消息数';
COMMENT ON COLUMN "publish_channel"."last_msg_at" IS '最近消息时间';
CREATE INDEX "idx_app_publish_channel" ON "publish_channel" ("app_id");
CREATE INDEX "idx_tenant_publish_channel" ON "publish_channel" ("tenant_id");

DROP TABLE IF EXISTS "publish_channel_msg" CASCADE;
CREATE TABLE "publish_channel_msg" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "channel_id" bigint NOT NULL,
  "app_id" bigint NOT NULL,
  "direction" varchar(8) NOT NULL DEFAULT 'inbound',
  "event_type" varchar(32),
  "from_user" varchar(128),
  "content" text,
  "reply" text,
  "status" varchar(16) NOT NULL DEFAULT 'success',
  "error_msg" varchar(512),
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "publish_channel_msg" IS '发布-渠道消息记录';
COMMENT ON COLUMN "publish_channel_msg"."id" IS '主键';
COMMENT ON COLUMN "publish_channel_msg"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "publish_channel_msg"."channel_id" IS '渠道ID';
COMMENT ON COLUMN "publish_channel_msg"."app_id" IS '应用ID';
COMMENT ON COLUMN "publish_channel_msg"."direction" IS '方向: inbound入站/outbound出站';
COMMENT ON COLUMN "publish_channel_msg"."event_type" IS '事件类型(如 message/event)';
COMMENT ON COLUMN "publish_channel_msg"."from_user" IS '来源用户标识(openid等)';
COMMENT ON COLUMN "publish_channel_msg"."content" IS '消息内容';
COMMENT ON COLUMN "publish_channel_msg"."reply" IS '回复内容';
COMMENT ON COLUMN "publish_channel_msg"."status" IS '处理状态: success/failed/skipped';
COMMENT ON COLUMN "publish_channel_msg"."error_msg" IS '失败原因';
CREATE INDEX "idx_channel" ON "publish_channel_msg" ("channel_id");
CREATE INDEX "idx_app_time_publish_channel_msg" ON "publish_channel_msg" ("app_id", "create_time");

DROP TABLE IF EXISTS "sys_announcement" CASCADE;
CREATE TABLE "sys_announcement" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "title" varchar(128) NOT NULL,
  "content" text,
  "scope" varchar(16) NULL DEFAULT 'all',
  "status" smallint NULL DEFAULT 0,
  "pinned" smallint NULL DEFAULT 0,
  "publish_time" timestamp,
  "offline_time" timestamp,
  "publisher" bigint,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" smallint NULL DEFAULT 0,
  "deleted_time" timestamp,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_announcement" IS '平台公告';
COMMENT ON COLUMN "sys_announcement"."id" IS '主键';
COMMENT ON COLUMN "sys_announcement"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_announcement"."title" IS '公告标题';
COMMENT ON COLUMN "sys_announcement"."content" IS '公告内容(支持换行的纯文本)';
COMMENT ON COLUMN "sys_announcement"."scope" IS '受众范围: all 全部用户';
COMMENT ON COLUMN "sys_announcement"."status" IS '状态: 0草稿 1发布中 2已下线';
COMMENT ON COLUMN "sys_announcement"."pinned" IS '是否置顶: 0否 1是';
COMMENT ON COLUMN "sys_announcement"."publish_time" IS '发布时间';
COMMENT ON COLUMN "sys_announcement"."offline_time" IS '下线时间';
COMMENT ON COLUMN "sys_announcement"."publisher" IS '发布人用户ID';
COMMENT ON COLUMN "sys_announcement"."deleted" IS '逻辑删除: 0正常 1回收站';
COMMENT ON COLUMN "sys_announcement"."deleted_time" IS '删除时间';
CREATE INDEX "idx_tenant_status_sys_announcement" ON "sys_announcement" ("tenant_id", "status");
CREATE INDEX "idx_deleted_sys_announcement" ON "sys_announcement" ("deleted");

INSERT INTO "sys_announcement" VALUES (1, 1, 'AgentForge 平台 v1.2 功能升级公告', '各位用户：

平台已于近期完成 v1.2 版本升级，本次升级新增以下能力：
1. 新增费用账单与月度预算提醒；
2. 新增发布渠道与应用市场模块；
3. 优化多智能体编排与运行观测体验。

如遇使用问题，可前往「帮助与文档」查看使用指南。', 'all', 1, 1, '2026-09-01 10:00:00', NULL, 1, '2026-09-01 10:00:00', '2026-09-01 10:00:00', 0, NULL);
INSERT INTO "sys_announcement" VALUES (2, 1, '关于数据安全使用的提醒（草稿）', '请勿在知识库与提示词中上传含敏感信息的资料，注意遵守数据安全规范。', 'all', 0, 0, NULL, NULL, 1, '2026-09-02 14:20:00', '2026-09-02 14:20:00', 0, NULL);
DROP TABLE IF EXISTS "sys_notification" CASCADE;
CREATE TABLE "sys_notification" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "user_id" bigint NOT NULL,
  "type" varchar(16) NOT NULL DEFAULT 'system',
  "title" varchar(200) NOT NULL,
  "content" text,
  "biz_type" varchar(32),
  "biz_id" bigint,
  "read" smallint NULL DEFAULT 0,
  "read_time" timestamp,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_notification" IS '站内通知';
COMMENT ON COLUMN "sys_notification"."id" IS '主键';
COMMENT ON COLUMN "sys_notification"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_notification"."user_id" IS '接收用户ID';
COMMENT ON COLUMN "sys_notification"."type" IS '类型: system系统/announcement公告/run任务/alert告警';
COMMENT ON COLUMN "sys_notification"."title" IS '标题';
COMMENT ON COLUMN "sys_notification"."content" IS '内容';
COMMENT ON COLUMN "sys_notification"."biz_type" IS '业务类型(如 announcement)';
COMMENT ON COLUMN "sys_notification"."biz_id" IS '业务ID';
COMMENT ON COLUMN "sys_notification"."read" IS '是否已读: 0未读 1已读';
COMMENT ON COLUMN "sys_notification"."read_time" IS '阅读时间';
CREATE INDEX "idx_user_read" ON "sys_notification" ("tenant_id", "user_id", "read");
CREATE INDEX "idx_biz" ON "sys_notification" ("biz_type", "biz_id");

DROP TABLE IF EXISTS "sys_oper_log" CASCADE;
CREATE TABLE "sys_oper_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "user_id" bigint,
  "username" varchar(64),
  "module" varchar(64),
  "operation" varchar(128),
  "method" varchar(10),
  "uri" varchar(255),
  "ip" varchar(64),
  "success" smallint NULL DEFAULT 1,
  "error_msg" varchar(1000),
  "cost_ms" integer,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_oper_log" IS '操作日志';
COMMENT ON COLUMN "sys_oper_log"."id" IS '主键';
COMMENT ON COLUMN "sys_oper_log"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_oper_log"."user_id" IS '操作人ID';
COMMENT ON COLUMN "sys_oper_log"."username" IS '操作人登录名';
COMMENT ON COLUMN "sys_oper_log"."module" IS '所属模块';
COMMENT ON COLUMN "sys_oper_log"."operation" IS '操作内容';
COMMENT ON COLUMN "sys_oper_log"."method" IS 'HTTP 方法';
COMMENT ON COLUMN "sys_oper_log"."uri" IS '请求路径';
COMMENT ON COLUMN "sys_oper_log"."ip" IS '来源IP';
COMMENT ON COLUMN "sys_oper_log"."success" IS '是否成功: 0失败 1成功';
COMMENT ON COLUMN "sys_oper_log"."error_msg" IS '错误信息';
COMMENT ON COLUMN "sys_oper_log"."cost_ms" IS '耗时(毫秒)';
COMMENT ON COLUMN "sys_oper_log"."create_time" IS '操作时间';
CREATE INDEX "idx_tenant_time" ON "sys_oper_log" ("tenant_id", "create_time");
CREATE INDEX "idx_user" ON "sys_oper_log" ("user_id");

