DROP TABLE IF EXISTS "sys_tenant" CASCADE;
CREATE TABLE "sys_tenant" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(64) NOT NULL,
  "code" varchar(32) NOT NULL,
  "plan" varchar(16) NULL DEFAULT 'free',
  "status" smallint NULL DEFAULT 1,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_tenant" IS '租户';
COMMENT ON COLUMN "sys_tenant"."id" IS '主键';
COMMENT ON COLUMN "sys_tenant"."name" IS '租户名称';
COMMENT ON COLUMN "sys_tenant"."code" IS '租户编码';
COMMENT ON COLUMN "sys_tenant"."plan" IS '套餐: free/pro/enterprise';
COMMENT ON COLUMN "sys_tenant"."status" IS '状态: 0禁用 1启用';
CREATE UNIQUE INDEX "uk_code" ON "sys_tenant" ("code");

INSERT INTO "sys_tenant" VALUES (1, '默认租户', 'default', 'pro', 1, '2026-08-28 00:22:58', '2026-08-28 00:22:58');
DROP TABLE IF EXISTS "sys_user" CASCADE;
CREATE TABLE "sys_user" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "username" varchar(64) NOT NULL,
  "password" varchar(128),
  "nickname" varchar(64),
  "email" varchar(128),
  "avatar" varchar(512),
  "status" smallint NULL DEFAULT 1,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_user" IS '用户';
COMMENT ON COLUMN "sys_user"."id" IS '主键';
COMMENT ON COLUMN "sys_user"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_user"."username" IS '登录名';
COMMENT ON COLUMN "sys_user"."password" IS '密码(BCrypt)';
COMMENT ON COLUMN "sys_user"."nickname" IS '昵称';
COMMENT ON COLUMN "sys_user"."email" IS '邮箱';
COMMENT ON COLUMN "sys_user"."avatar" IS '头像';
COMMENT ON COLUMN "sys_user"."status" IS '状态: 0禁用 1启用';
CREATE UNIQUE INDEX "uk_username" ON "sys_user" ("username");
CREATE INDEX "idx_tenant_sys_user" ON "sys_user" ("tenant_id");

