DROP TABLE IF EXISTS "sys_user_security" CASCADE;
CREATE TABLE "sys_user_security" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "user_id" bigint NOT NULL,
  "phone" varchar(32),
  "mfa_enabled" smallint NOT NULL DEFAULT 0,
  "mfa_secret" varchar(128),
  "mfa_bound_at" timestamp,
  "last_login_at" timestamp,
  "last_login_ip" varchar(64),
  "login_count" integer NOT NULL DEFAULT 0,
  "create_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_user_security" IS '账号安全扩展';
COMMENT ON COLUMN "sys_user_security"."id" IS '主键';
COMMENT ON COLUMN "sys_user_security"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_user_security"."user_id" IS '用户ID';
COMMENT ON COLUMN "sys_user_security"."phone" IS '手机号';
COMMENT ON COLUMN "sys_user_security"."mfa_enabled" IS 'MFA二次验证: 0关闭 1开启';
COMMENT ON COLUMN "sys_user_security"."mfa_secret" IS 'MFA密钥(Base32)';
COMMENT ON COLUMN "sys_user_security"."mfa_bound_at" IS 'MFA绑定时间';
COMMENT ON COLUMN "sys_user_security"."last_login_at" IS '最近登录时间';
COMMENT ON COLUMN "sys_user_security"."last_login_ip" IS '最近登录IP';
COMMENT ON COLUMN "sys_user_security"."login_count" IS '累计登录次数';
CREATE UNIQUE INDEX "uk_user" ON "sys_user_security" ("user_id");

